// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Arrays;
import java.util.Random;

import org.junit.jupiter.api.Test;

class LmdbNativeSipFilterTest {

	@Test
	void exactUnsignedDomainHasNoFalseResults() {
		Random random = new Random(17);
		Long[] boxed = new Long[4096];
		for (int i = 0; i < boxed.length; i++) {
			boxed[i] = random.nextLong();
		}
		Arrays.sort(boxed, Long::compareUnsigned);
		long[] values = new long[boxed.length];
		for (int i = 0; i < values.length; i++) {
			values[i] = boxed[i];
		}
		LmdbNativeSipFilter.Domain domain = LmdbNativeSipFilter.sorted(values, 0, values.length, true);
		for (long value : values) {
			assertTrue(domain.mayContain(value));
		}
		assertTrue(domain.exact());
	}

	@Test
	void bloomFallbackNeverRejectsAnInsertedValue() {
		Random random = new Random(19);
		long[] values = new long[100_000];
		LmdbNativeSipFilter.Builder builder = LmdbNativeSipFilter.builder(values.length, 32 * 1024, true);
		for (int i = 0; i < values.length; i++) {
			values[i] = random.nextLong();
			builder.accept(values[i]);
		}
		LmdbNativeSipFilter.Domain domain = builder.build();
		for (long value : values) {
			assertTrue(domain.mayContain(value));
		}
		assertFalse(domain.exact());
	}

	@Test
	void affineDomainUsesExactMembershipAndLowerBound() {
		LmdbNativeSipFilter.Domain domain = LmdbNativeSipFilter.affine(100, 8, 1000);
		assertTrue(domain.mayContain(100 + 8L * 999));
		assertFalse(domain.mayContain(101 + 8L * 999));
		assertEquals(4, domain.lowerBound(126));
	}
}
